NUL = -1

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def longestConsecutiveEither(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    inc = [1] * n
    dec = [1] * n
    best = 0
    for k in range(n - 1, -1, -1):
        for c in (left[k], right[k]):
            if c == -1:
                continue
            if vals[c] == vals[k] + 1 and inc[c] + 1 > inc[k]:
                inc[k] = inc[c] + 1
            elif vals[c] == vals[k] - 1 and dec[c] + 1 > dec[k]:
                dec[k] = dec[c] + 1
        best = max(best, inc[k] + dec[k] - 1)
    return best
